    /// The mock exams shown in the app: hand-authored, each written independently.
    /// Validated together with `ContentValidator.validateBank`, so cross-exam reuse fails.
    public static let allExams: [MockExam] = {
        let exams = AuthoredExams.all
        let audit = ContentValidator().validateBank(exams)
        return zip(exams, audit.reports).map { exam, report in
            exam.withValidation(report, generatorModel: exam.provenance.generatorModel)
        }
    }()

    /// The original 30 slot-filled template exams (audit 2026-11-25, finding 1).
    /// Not shown in the app. Kept so the test suite can confirm the cross-exam validator rejects them.
    public static let legacyTemplateExams: [MockExam] = {
        let exams = blueprints.map(buildExam(from:))
        let audit = ContentValidator().validateBank(exams)
        return zip(exams, audit.reports).map { exam, report in
            exam.withValidation(report, generatorModel: "Slot-filled template (legacy, superseded)")
        }
    }()

    // MARK: - Exam Builder

    private static func buildExam(from bp: ExamBlueprint) -> MockExam {
        let examID = String(format: "mock-%02d", bp.number)
        let listeningParts = buildListeningParts(examID: examID, bp: bp)
        let readingPassages = buildReadingPassages(examID: examID, bp: bp)
        let task1 = buildWritingTask1(examID: examID, bp: bp)
        let task2 = WritingTask2Prompt(
            id: "\(examID)-wt2",
            title: "Mock \(bp.number) Task 2: \(bp.theme)",
            essayType: bp.essayType,
            topicDomain: bp.theme,
            promptText: bp.essayPrompt,
            minimumWords: 250
        )
        let speaking = buildSpeakingSet(examID: examID, bp: bp)

        return MockExam(
            id: examID,
            examNumber: bp.number,
            title: "Mock Exam \(bp.number): \(bp.title)",
            difficulty: bp.difficulty,
            theme: bp.theme,
            listeningParts: listeningParts,
            readingPassages: readingPassages,
            writingTask1: task1,
            writingTask2: task2,
            speakingSet: speaking,
            provenance: ContentProvenance(origin: .originalPractice, isOfficialIELTSMaterial: false)
        )
    }

    // MARK: - Listening Builder (4 Parts, 40 Questions)

    private static func buildListeningParts(examID: String, bp: ExamBlueprint) -> [ListeningPart] {
        let accents: [EnglishAccent] = [.british, .australian, .irish, .american, .canadian]
        let a1 = accents[(bp.number - 1) % accents.count]
        let a2 = accents[bp.number % accents.count]
        let a3 = accents[(bp.number + 1) % accents.count]
        let a4 = accents[(bp.number + 2) % accents.count]

        let fee = 120 + (bp.number * 5)
        let roomCode = "B\(10 + bp.number)"
        let refCode = "IM-\(400 + bp.number)"
        let yearEnd = bp.yearStart + 8

        // Part 1: Social / Registration Conversation (Q1–10)
        let p1Dialogue = [
            DialogueTurn(speaker: "Coordinator", accent: a1, text: "Good morning, \(bp.institution) visitor desk in \(bp.city). How can I help you today?"),
            DialogueTurn(speaker: "Caller", accent: a2, text: "Hello, I would like to register for the open seminar on \(bp.discipline1) starting on Tuesday. Actually, sorry, I meant Thursday morning at nine thirty."),
            DialogueTurn(speaker: "Coordinator", accent: a1, text: "No problem. Thursday is confirmed. The standard workshop fee is \(fee) euros, which includes printed field notes and lunch in room \(roomCode)."),
            DialogueTurn(speaker: "Caller", accent: a2, text: "Great. Should I bring a laptop or a tablet? And is parking available near the east gate?"),
            DialogueTurn(speaker: "Coordinator", accent: a1, text: "Please bring a laptop for the data workshop. Parking at the east gate is closed for repairs, so use the north car park instead. Your booking reference is \(refCode)."),
            DialogueTurn(speaker: "Caller", accent: a2, text: "Wonderful. Can I also request vegetarian lunch and a certificate of attendance for my university supervisor?"),
            DialogueTurn(speaker: "Coordinator", accent: a1, text: "Certainly, I have noted vegetarian lunch and a digital certificate. The seminar focuses on \(bp.keyTerm1) applications and concludes at four fifteen.")
        ]

        let p1Questions: [ExamQuestion] = [
            ExamQuestion(id: "\(examID)-L01", number: 1, format: .formCompletion, prompt: "City hosting the seminar (ONE WORD):", acceptedAnswers: [bp.city], maxWordCount: 1, explanation: "The coordinator states the desk is in \(bp.city).", arabicExplanation: "المدينة المذكورة في بداية المكالمة هي \(bp.city).", evidenceQuote: bp.city, skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L02", number: 2, format: .formCompletion, prompt: "Confirmed day of the seminar (ONE WORD):", acceptedAnswers: ["Thursday"], maxWordCount: 1, explanation: "The caller self-corrects from Tuesday to Thursday.", arabicExplanation: "المتحدث صحح اليوم من الثلاثاء إلى الخميس (مشتت شائع في IELTS).", evidenceQuote: "Thursday", distractorNote: "Tuesday is mentioned first and then corrected.", skillTag: "distractor_correction"),
            ExamQuestion(id: "\(examID)-L03", number: 3, format: .formCompletion, prompt: "Standard workshop fee in euros (NUMBER ONLY):", acceptedAnswers: ["\(fee)", "\(fee) euros"], maxWordCount: 2, explanation: "The fee stated is \(fee) euros.", evidenceQuote: "\(fee)", skillTag: "numbers"),
            ExamQuestion(id: "\(examID)-L04", number: 4, format: .formCompletion, prompt: "Room code for lunch and notes (ONE CODE):", acceptedAnswers: [roomCode], maxWordCount: 1, explanation: "Lunch and notes are in room \(roomCode).", evidenceQuote: roomCode, skillTag: "alphanumeric"),
            ExamQuestion(id: "\(examID)-L05", number: 5, format: .noteCompletion, prompt: "Device required for the data workshop (ONE WORD):", acceptedAnswers: ["laptop"], maxWordCount: 1, explanation: "The coordinator asks participants to bring a laptop.", evidenceQuote: "laptop", distractorNote: "Tablet is asked about but laptop is required.", skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L06", number: 6, format: .noteCompletion, prompt: "Open car park location (ONE WORD):", acceptedAnswers: ["north"], maxWordCount: 1, explanation: "East gate is closed; visitors must use the north car park.", evidenceQuote: "north", distractorNote: "East gate is closed for repairs.", skillTag: "distractor_correction"),
            ExamQuestion(id: "\(examID)-L07", number: 7, format: .formCompletion, prompt: "Booking reference code:", acceptedAnswers: [refCode], maxWordCount: 2, explanation: "The reference code is \(refCode).", evidenceQuote: refCode, skillTag: "alphanumeric"),
            ExamQuestion(id: "\(examID)-L08", number: 8, format: .noteCompletion, prompt: "Dietary preference recorded (ONE WORD):", acceptedAnswers: ["vegetarian"], maxWordCount: 1, explanation: "The caller requests a vegetarian lunch.", evidenceQuote: "vegetarian", skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L09", number: 9, format: .noteCompletion, prompt: "Format of the attendance certificate (ONE WORD):", acceptedAnswers: ["digital"], maxWordCount: 1, explanation: "The coordinator confirms a digital certificate.", evidenceQuote: "digital", skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L10", number: 10, format: .sentenceCompletion, prompt: "The seminar highlights practical applications of ___ (ONE OR TWO WORDS):", acceptedAnswers: [bp.keyTerm1], maxWordCount: 2, explanation: "The seminar focuses on \(bp.keyTerm1) applications.", evidenceQuote: bp.keyTerm1, skillTag: "listening_detail")
        ]

        // Part 2: Social Monologue / Facility Orientation (Q11–20)
        let p2Dialogue = [
            DialogueTurn(speaker: "Site Guide", accent: a2, text: "Welcome everyone to the public tour of \(bp.institution). Before we begin, please keep your visitor badges visible and leave backpacks in the ground-floor lockers rather than the reception desk."),
            DialogueTurn(speaker: "Site Guide", accent: a2, text: "Looking at your site map, the main exhibition gallery sits directly north of the courtyard, while the greenhouse wing is located on the western side beside the weather station."),
            DialogueTurn(speaker: "Site Guide", accent: a2, text: "Our interactive \(bp.discipline2) exhibit opened in \(bp.yearStart) and tracks a \(bp.metricValue) \(bp.unit) improvement in regional efficiency. Guided demonstrations run every forty-five minutes."),
            DialogueTurn(speaker: "Site Guide", accent: a2, text: "At midday, the courtyard cafe serves local produce, and our bookshop opposite the auditorium stocks open-access manuals on \(bp.keyTerm2). Photography is permitted without flash in all public galleries.")
        ]

        let p2Questions: [ExamQuestion] = [
            ExamQuestion(id: "\(examID)-L11", number: 11, format: .multipleChoice, prompt: "Where should visitors store backpacks during the tour?", options: ["A. At the reception desk", "B. In ground-floor lockers", "C. Inside the auditorium"], acceptedAnswers: ["B", "B. In ground-floor lockers", "ground-floor lockers", "lockers"], explanation: "Backpacks go in the ground-floor lockers rather than reception.", evidenceQuote: "lockers", distractorNote: "Reception desk is mentioned as the wrong place.", skillTag: "multiple_choice"),
            ExamQuestion(id: "\(examID)-L12", number: 12, format: .diagramLabeling, prompt: "Map label: Direction of the main exhibition gallery from the courtyard (ONE WORD):", acceptedAnswers: ["north"], maxWordCount: 1, explanation: "The gallery sits directly north of the courtyard.", evidenceQuote: "north", skillTag: "map_labeling"),
            ExamQuestion(id: "\(examID)-L13", number: 13, format: .diagramLabeling, prompt: "Map label: Side of the site where the greenhouse wing is located (ONE WORD):", acceptedAnswers: ["western", "west"], maxWordCount: 1, explanation: "The greenhouse wing is on the western side.", evidenceQuote: "western", skillTag: "map_labeling"),
            ExamQuestion(id: "\(examID)-L14", number: 14, format: .diagramLabeling, prompt: "Map label: Facility beside the greenhouse wing (TWO WORDS):", acceptedAnswers: ["weather station"], maxWordCount: 2, explanation: "It is beside the weather station.", evidenceQuote: "weather station", skillTag: "map_labeling"),
            ExamQuestion(id: "\(examID)-L15", number: 15, format: .tableCompletion, prompt: "Year the interactive exhibit opened (NUMBER):", acceptedAnswers: ["\(bp.yearStart)"], maxWordCount: 1, explanation: "The exhibit opened in \(bp.yearStart).", evidenceQuote: "\(bp.yearStart)", skillTag: "numbers"),
            ExamQuestion(id: "\(examID)-L16", number: 16, format: .tableCompletion, prompt: "Measured regional efficiency gain figure (NUMBER):", acceptedAnswers: ["\(bp.metricValue)"], maxWordCount: 1, explanation: "The guide reports a \(bp.metricValue) \(bp.unit) improvement.", evidenceQuote: "\(bp.metricValue)", skillTag: "numbers"),
            ExamQuestion(id: "\(examID)-L17", number: 17, format: .shortAnswer, prompt: "How often do guided demonstrations run? (IN MINUTES):", acceptedAnswers: ["45", "forty-five", "45 minutes", "forty-five minutes"], maxWordCount: 2, explanation: "Demonstrations run every forty-five minutes.", evidenceQuote: "forty-five", skillTag: "numbers"),
            ExamQuestion(id: "\(examID)-L18", number: 18, format: .matching, prompt: "Location directly opposite the bookshop (ONE WORD):", acceptedAnswers: ["auditorium"], maxWordCount: 1, explanation: "The bookshop is opposite the auditorium.", evidenceQuote: "auditorium", skillTag: "map_labeling"),
            ExamQuestion(id: "\(examID)-L19", number: 19, format: .summaryCompletion, prompt: "The bookshop stocks open-access manuals on ___ (ONE OR TWO WORDS):", acceptedAnswers: [bp.keyTerm2], maxWordCount: 2, explanation: "The manuals cover \(bp.keyTerm2).", evidenceQuote: bp.keyTerm2, skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L20", number: 20, format: .multipleChoice, prompt: "What is the rule regarding photography in public galleries?", options: ["A. Strictly forbidden", "B. Permitted without flash", "C. Only allowed in the courtyard"], acceptedAnswers: ["B", "B. Permitted without flash", "permitted without flash"], explanation: "Photography is permitted without flash in all public galleries.", evidenceQuote: "without flash", skillTag: "multiple_choice")
        ]

        // Part 3: University Academic Discussion (Q21–30)
        let p3Dialogue = [
            DialogueTurn(speaker: "Tutor", accent: a3, text: "So, Liam and Maya, let's review your joint dissertation proposal on \(bp.discipline1) and \(bp.discipline3). How did you decide on your sample size?"),
            DialogueTurn(speaker: "Liam", accent: a1, text: "Initially I wanted to survey thirty sites, but Maya pointed out that statistical power would be too weak, so we agreed on sixty sites across three counties."),
            DialogueTurn(speaker: "Maya", accent: a4, text: "Right, and we are following the protocol published by \(bp.scientist) in \(yearEnd). The trickiest stage is calibrating the baseline sensors before winter rainfall."),
            DialogueTurn(speaker: "Tutor", accent: a3, text: "Good catch. What about your literature review? Have you separated peer-reviewed field studies from policy briefs?"),
            DialogueTurn(speaker: "Liam", accent: a1, text: "Yes, we built a comparison matrix. Most earlier papers measured \(bp.keyTerm1), whereas very few examined \(bp.keyTerm3) alongside economic cost."),
            DialogueTurn(speaker: "Maya", accent: a4, text: "We plan to submit the ethics form by Friday, run the pilot dataset in October, and present preliminary charts at the departmental colloquium.")
        ]

        let p3Questions: [ExamQuestion] = [
            ExamQuestion(id: "\(examID)-L21", number: 21, format: .multipleChoice, prompt: "How many field sites did the students finally agree to sample?", options: ["A. 30 sites", "B. 60 sites", "C. 90 sites"], acceptedAnswers: ["B", "B. 60 sites", "60", "sixty"], explanation: "Liam initially proposed 30, but they agreed on 60 sites.", evidenceQuote: "sixty", distractorNote: "30 is mentioned as Liam's rejected initial idea.", skillTag: "distractor_correction"),
            ExamQuestion(id: "\(examID)-L22", number: 22, format: .shortAnswer, prompt: "Across how many counties will data be collected? (NUMBER):", acceptedAnswers: ["3", "three"], maxWordCount: 1, explanation: "Data spans three counties.", evidenceQuote: "three", skillTag: "numbers"),
            ExamQuestion(id: "\(examID)-L23", number: 23, format: .sentenceCompletion, prompt: "They are adapting a protocol published by ___:", acceptedAnswers: [bp.scientist], maxWordCount: 3, explanation: "Maya names \(bp.scientist).", evidenceQuote: bp.scientist, skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L24", number: 24, format: .tableCompletion, prompt: "Publication year of the reference protocol (NUMBER):", acceptedAnswers: ["\(yearEnd)"], maxWordCount: 1, explanation: "Published in \(yearEnd).", evidenceQuote: "\(yearEnd)", skillTag: "numbers"),
            ExamQuestion(id: "\(examID)-L25", number: 25, format: .multipleChoice, prompt: "Which stage does Maya consider the most challenging?", options: ["A. Printing questionnaires", "B. Calibrating baseline sensors", "C. Booking transport"], acceptedAnswers: ["B", "B. Calibrating baseline sensors", "calibrating baseline sensors"], explanation: "Maya says calibrating baseline sensors before winter rainfall is trickiest.", evidenceQuote: "calibrating", skillTag: "multiple_choice"),
            ExamQuestion(id: "\(examID)-L26", number: 26, format: .flowchartCompletion, prompt: "Tool used by the students to organize their literature review (TWO WORDS):", acceptedAnswers: ["comparison matrix"], maxWordCount: 2, explanation: "Liam says they built a comparison matrix.", evidenceQuote: "comparison matrix", skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L27", number: 27, format: .summaryCompletion, prompt: "Few prior studies combined economic cost with ___ (ONE OR TWO WORDS):", acceptedAnswers: [bp.keyTerm3], maxWordCount: 2, explanation: "Liam notes very few examined \(bp.keyTerm3) alongside economic cost.", evidenceQuote: bp.keyTerm3, skillTag: "listening_detail"),
            ExamQuestion(id: "\(examID)-L28", number: 28, format: .flowchartCompletion, prompt: "Document scheduled for submission by Friday (TWO WORDS):", acceptedAnswers: ["ethics form"], maxWordCount: 2, explanation: "They plan to submit the ethics form by Friday.", evidenceQuote: "ethics form", skillTag: "flowchart"),
            ExamQuestion(id: "\(examID)-L29", number: 29, format: .flowchartCompletion, prompt: "Month planned for the pilot dataset (ONE WORD):", acceptedAnswers: ["October"], maxWordCount: 1, explanation: "The pilot dataset runs in October.", evidenceQuote: "October", skillTag: "flowchart"),
            ExamQuestion(id: "\(examID)-L30", number: 30, format: .noteCompletion, prompt: "Venue where preliminary charts will be presented (TWO WORDS):", acceptedAnswers: ["departmental colloquium", "colloquium"], maxWordCount: 2, explanation: "They will present at the departmental colloquium.", evidenceQuote: "colloquium", skillTag: "listening_detail")
        ]

        // Part 4: Academic Lecture Monologue (Q31–40)
        let p4Dialogue = [
            DialogueTurn(speaker: "Lecturer", accent: a4, text: "Today's lecture examines long-term resilience in \(bp.theme), drawing on empirical evidence from \(bp.discipline1) and \(bp.discipline3)."),
            DialogueTurn(speaker: "Lecturer", accent: a4, text: "Historically, planners relied on single-variable models that prioritized short-term output. However, field datasets collected since \(bp.yearStart) reveal that ignoring systemic feedback loops creates hidden vulnerability."),
            DialogueTurn(speaker: "Lecturer", accent: a4, text: "A pivotal study led by \(bp.scientist) demonstrated three core mechanisms. First, integrating \(bp.keyTerm1) stabilized baseline performance under seasonal stress. Second, optimizing \(bp.keyTerm2) reduced operational waste by \(bp.metricValue) \(bp.unit). Third, continuous monitoring of \(bp.keyTerm3) enabled early intervention before thresholds were breached."),
            DialogueTurn(speaker: "Lecturer", accent: a4, text: "Critics initially questioned whether small-scale operators could afford automated diagnostics. Nevertheless, cooperative sharing models in \(bp.city) lowered per-unit costs by nearly half, proving that institutional design matters as much as engineering hardware.")
        ]

        let p4Questions: [ExamQuestion] = [
            ExamQuestion(id: "\(examID)-L31", number: 31, format: .noteCompletion, prompt: "Core focus of today's lecture: long-term ___ (ONE WORD):", acceptedAnswers: ["resilience"], maxWordCount: 1, explanation: "The lecture examines long-term resilience.", evidenceQuote: "resilience", skillTag: "lecture_notes"),
            ExamQuestion(id: "\(examID)-L32", number: 32, format: .noteCompletion, prompt: "Early models prioritized short-term ___ (ONE WORD):", acceptedAnswers: ["output"], maxWordCount: 1, explanation: "Single-variable models prioritized short-term output.", evidenceQuote: "output", skillTag: "lecture_notes"),
            ExamQuestion(id: "\(examID)-L33", number: 33, format: .sentenceCompletion, prompt: "Ignoring systemic ___ loops creates hidden vulnerability (ONE WORD):", acceptedAnswers: ["feedback"], maxWordCount: 1, explanation: "Ignoring systemic feedback loops creates hidden vulnerability.", evidenceQuote: "feedback", skillTag: "lecture_notes"),
            ExamQuestion(id: "\(examID)-L34", number: 34, format: .noteCompletion, prompt: "Mechanism 1: Integrating ___ stabilized baseline performance (ONE OR TWO WORDS):", acceptedAnswers: [bp.keyTerm1], maxWordCount: 2, explanation: "Integrating \(bp.keyTerm1) stabilized baseline performance.", evidenceQuote: bp.keyTerm1, skillTag: "lecture_notes"),
            ExamQuestion(id: "\(examID)-L35", number: 35, format: .noteCompletion, prompt: "Mechanism 2: Optimizing ___ reduced operational waste (ONE OR TWO WORDS):", acceptedAnswers: [bp.keyTerm2], maxWordCount: 2, explanation: "Optimizing \(bp.keyTerm2) reduced waste.", evidenceQuote: bp.keyTerm2, skillTag: "lecture_notes"),
            ExamQuestion(id: "\(examID)-L36", number: 36, format: .noteCompletion, prompt: "Mechanism 3: Monitoring ___ enabled early intervention (ONE OR TWO WORDS):", acceptedAnswers: [bp.keyTerm3], maxWordCount: 2, explanation: "Continuous monitoring of \(bp.keyTerm3) enabled early intervention.", evidenceQuote: bp.keyTerm3, skillTag: "lecture_notes"),
            ExamQuestion(id: "\(examID)-L37", number: 37, format: .multipleChoice, prompt: "What initial concern did critics raise?", options: ["A. Lack of university interest", "B. Affordability for small-scale operators", "C. Excessive government regulation"], acceptedAnswers: ["B", "B. Affordability for small-scale operators"], explanation: "Critics questioned whether small-scale operators could afford automated diagnostics.", evidenceQuote: "afford", skillTag: "multiple_choice"),
            ExamQuestion(id: "\(examID)-L38", number: 38, format: .summaryCompletion, prompt: "Strategy that lowered per-unit diagnostic costs: ___ sharing models (ONE WORD):", acceptedAnswers: ["cooperative"], maxWordCount: 1, explanation: "Cooperative sharing models lowered costs.", evidenceQuote: "cooperative", skillTag: "lecture_notes"),
            ExamQuestion(id: "\(examID)-L39", number: 39, format: .shortAnswer, prompt: "By approximately what fraction were per-unit costs lowered? (ONE WORD):", acceptedAnswers: ["half", "50%"], maxWordCount: 1, explanation: "Costs dropped by nearly half.", evidenceQuote: "half", skillTag: "numbers"),
            ExamQuestion(id: "\(examID)-L40", number: 40, format: .sentenceCompletion, prompt: "The lecturer concludes that institutional ___ matters as much as engineering hardware (ONE WORD):", acceptedAnswers: ["design"], maxWordCount: 1, explanation: "Institutional design matters as much as engineering hardware.", evidenceQuote: "design", skillTag: "lecture_notes")
        ]

        return [
            ListeningPart(id: "\(examID)-LP1", partNumber: 1, title: "Part 1: Seminar Registration (\(bp.city))", contextDescription: "Everyday administrative telephone conversation.", primaryAccent: a1, dialogue: p1Dialogue, questions: p1Questions, keyVocabulary: [bp.keyTerm1, "certificate", "booking reference"]),
            ListeningPart(id: "\(examID)-LP2", partNumber: 2, title: "Part 2: Orientation at \(bp.institution)", contextDescription: "Public tour briefing and site map orientation.", primaryAccent: a2, dialogue: p2Dialogue, questions: p2Questions, keyVocabulary: [bp.keyTerm2, "courtyard", "open-access"]),
            ListeningPart(id: "\(examID)-LP3", partNumber: 3, title: "Part 3: Dissertation Planning Seminar", contextDescription: "University tutor and two students refining research methodology.", primaryAccent: a3, dialogue: p3Dialogue, questions: p3Questions, keyVocabulary: [bp.keyTerm3, "statistical power", "colloquium"]),
            ListeningPart(id: "\(examID)-LP4", partNumber: 4, title: "Part 4: Academic Lecture on \(bp.theme)", contextDescription: "University lecture on systemic resilience and institutional design.", primaryAccent: a4, dialogue: p4Dialogue, questions: p4Questions, keyVocabulary: ["resilience", "feedback loops", "cooperative"])
        ]
    }

    // MARK: - Academic Reading Builder (3 Passages, 40 Questions: 13 + 13 + 14)

    private static func buildReadingPassages(examID: String, bp: ExamBlueprint) -> [ReadingPassage] {
        let yearEnd = bp.yearStart + 9

        // Passage 1 (13 questions: Q1–13)
        let p1Paragraphs = [
            "Over the past decade, researchers in \(bp.discipline1) have re-evaluated conventional assumptions regarding resource efficiency. Field trials initiated in \(bp.yearStart) at \(bp.institution) near \(bp.city) demonstrated that integrating \(bp.keyTerm1) into established workflows can stabilize seasonal output without increasing synthetic inputs. Rather than relying solely on laboratory simulations, investigators tracked commercial operations across varying weather patterns to capture realistic operational variability.",
            "Led by \(bp.scientist), the longitudinal team measured a \(bp.metricValue) \(bp.unit) improvement in baseline performance by \(yearEnd). Crucially, the gains were not uniform across every participating site. Operations that combined technical upgrades with structured staff training outperformed passive adopters by a substantial margin, suggesting that human management remains decisive even in sensor-rich environments.",
            "Economic audits accompanying the scientific study challenged the belief that sustainable transitions inevitably erode profitability. While upfront capital costs deterred some smaller enterprises during the first two years, lower input expenditure and reduced waste disposal fees enabled most participants to reach break-even within thirty-six months. Policy analysts now cite the \(bp.city) framework as a replicable model for balancing ecological stewardship with commercial viability.",
            "Nevertheless, several methodological caveats warrant caution. Because participating sites volunteered for the study, selection bias may have inflated early compliance rates. Future multi-region trials incorporating randomized control groups will be required to confirm whether comparable outcomes hold under harsher climatic extremes."
        ]

        let p1Questions: [ExamQuestion] = [
            ExamQuestion(id: "\(examID)-R01", number: 1, format: .trueFalseNotGiven, prompt: "The field trials at \(bp.institution) relied exclusively on laboratory simulations.", options: ["TRUE", "FALSE", "NOT GIVEN"], acceptedAnswers: ["FALSE"], explanation: "Paragraph A states investigators tracked commercial operations rather than relying solely on laboratory simulations.", evidenceQuote: "laboratory simulations", distractorNote: "Watch for extreme qualifier 'exclusively'.", skillTag: "tfng"),
            ExamQuestion(id: "\(examID)-R02", number: 2, format: .trueFalseNotGiven, prompt: "Integrating \(bp.keyTerm1) helped stabilize seasonal output without raising synthetic inputs.", options: ["TRUE", "FALSE", "NOT GIVEN"], acceptedAnswers: ["TRUE"], explanation: "Paragraph A directly confirms this finding.", evidenceQuote: bp.keyTerm1, skillTag: "tfng"),
            ExamQuestion(id: "\(examID)-R03", number: 3, format: .trueFalseNotGiven, prompt: "All participating sites recorded identical performance improvements.", options: ["TRUE", "FALSE", "NOT GIVEN"], acceptedAnswers: ["FALSE"], explanation: "Paragraph B explicitly states that the gains were not uniform across every participating site.", evidenceQuote: "not uniform", skillTag: "tfng"),
            ExamQuestion(id: "\(examID)-R04", number: 4, format: .trueFalseNotGiven, prompt: "\(bp.scientist) previously worked for an international banking regulator.", options: ["TRUE", "FALSE", "NOT GIVEN"], acceptedAnswers: ["NOT GIVEN"], explanation: "The passage makes no mention of \(bp.scientist)'s prior employment in banking.", evidenceQuote: bp.scientist, skillTag: "tfng"),
            ExamQuestion(id: "\(examID)-R05", number: 5, format: .trueFalseNotGiven, prompt: "Most participating enterprises recovered their upfront investment within three years.", options: ["TRUE", "FALSE", "NOT GIVEN"], acceptedAnswers: ["TRUE"], explanation: "Paragraph C states most participants reached break-even within thirty-six months (three years).", evidenceQuote: "thirty-six months", skillTag: "paraphrasing"),
            ExamQuestion(id: "\(examID)-R06", number: 6, format: .matchingHeadings, prompt: "Choose the best heading for Paragraph B:", options: ["i. Why management skill amplifies technical gains", "ii. Historical origins of weather forecasting", "iii. Legal barriers to international exports"], acceptedAnswers: ["i", "i. Why management skill amplifies technical gains"], explanation: "Paragraph B emphasizes that sites combining technical upgrades with staff training outperformed passive adopters.", evidenceQuote: "staff training", skillTag: "matching_headings"),
            ExamQuestion(id: "\(examID)-R07", number: 7, format: .matchingHeadings, prompt: "Choose the best heading for Paragraph D:", options: ["i. Guaranteed global scalability", "ii. Methodological limits and next research steps", "iii. How to apply for capital grants"], acceptedAnswers: ["ii", "ii. Methodological limits and next research steps"], explanation: "Paragraph D discusses selection bias and the need for randomized control groups.", evidenceQuote: "selection bias", skillTag: "matching_headings"),
            ExamQuestion(id: "\(examID)-R08", number: 8, format: .sentenceCompletion, prompt: "Field trials began in the year ___ (NUMBER):", acceptedAnswers: ["\(bp.yearStart)"], maxWordCount: 1, explanation: "Paragraph A states trials were initiated in \(bp.yearStart).", evidenceQuote: "\(bp.yearStart)", skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R09", number: 9, format: .sentenceCompletion, prompt: "Operations pairing technical upgrades with structured ___ outperformed passive adopters (TWO WORDS):", acceptedAnswers: ["staff training"], maxWordCount: 2, explanation: "Paragraph B cites structured staff training.", evidenceQuote: "staff training", skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R10", number: 10, format: .summaryCompletion, prompt: "Lower input spending and reduced ___ disposal fees aided financial recovery (ONE WORD):", acceptedAnswers: ["waste"], maxWordCount: 1, explanation: "Paragraph C mentions reduced waste disposal fees.", evidenceQuote: "waste disposal", skillTag: "summary_completion"),
            ExamQuestion(id: "\(examID)-R11", number: 11, format: .shortAnswer, prompt: "What methodological bias may have inflated early compliance rates? (TWO WORDS):", acceptedAnswers: ["selection bias"], maxWordCount: 2, explanation: "Paragraph D identifies selection bias from voluntary participation.", evidenceQuote: "selection bias", skillTag: "inference"),
            ExamQuestion(id: "\(examID)-R12", number: 12, format: .shortAnswer, prompt: "What type of control groups are recommended for future trials? (ONE WORD):", acceptedAnswers: ["randomized"], maxWordCount: 1, explanation: "Paragraph D calls for randomized control groups.", evidenceQuote: "randomized", skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R13", number: 13, format: .multipleChoice, prompt: "What is the author's overall tone in Passage 1?", options: ["A. Dismissive of field research", "B. Cautiously optimistic and evidence-based", "C. Uncritically promotional"], acceptedAnswers: ["B", "B. Cautiously optimistic and evidence-based"], explanation: "The passage highlights verified gains while clearly noting selection bias and future trial needs.", evidenceQuote: "methodological caveats", skillTag: "inference")
        ]

        // Passage 2 (13 questions: Q14–26)
        let p2Paragraphs = [
            "Modern \(bp.discipline2) increasingly depends on cross-disciplinary measurement. For much of the twentieth century, specialists evaluated \(bp.keyTerm2) in isolation from broader social and economic constraints. That narrow framing frequently produced elegant engineering prototypes that failed once deployed in everyday municipal or commercial settings.",
            "Contemporary design frameworks instead adopt a three-stage diagnostic loop: baseline mapping, iterative pilot testing, and post-occupancy evaluation. In a landmark \(bp.city) case study, engineers initially assumed that automated controls would eliminate user error. However, post-occupancy audits revealed that opaque interfaces caused operators to override automated schedules manually.",
            "To resolve this friction, designers introduced transparent visual dashboards showing real-time energy and resource trade-offs. Within six months, manual overrides declined dramatically and system efficiency stabilized. Behavioural researchers attribute this turnaround to feedback visibility: when practitioners can inspect why a system recommends an adjustment, trust and compliance increase measurably.",
            "Standardization bodies now advise public agencies to embed usability testing into procurement contracts before large-scale rollouts. Although participatory testing adds roughly four weeks to project timelines, it prevents costly retrofits and accelerates adoption across diverse user groups."
        ]

        let p2Questions: [ExamQuestion] = [
            ExamQuestion(id: "\(examID)-R14", number: 14, format: .matchingInformation, prompt: "Which paragraph explains why automated schedules were manually overridden?", options: ["A", "B", "C", "D"], acceptedAnswers: ["B"], explanation: "Paragraph B explains that opaque interfaces caused operators to override automated schedules.", evidenceQuote: "opaque interfaces", skillTag: "matching_information"),
            ExamQuestion(id: "\(examID)-R15", number: 15, format: .matchingInformation, prompt: "Which paragraph introduces the concept of feedback visibility?", options: ["A", "B", "C", "D"], acceptedAnswers: ["C"], explanation: "Paragraph C discusses feedback visibility and trust.", evidenceQuote: "feedback visibility", skillTag: "matching_information"),
            ExamQuestion(id: "\(examID)-R16", number: 16, format: .matchingInformation, prompt: "Which paragraph mentions procurement contracts and timeline extensions?", options: ["A", "B", "C", "D"], acceptedAnswers: ["D"], explanation: "Paragraph D discusses embedding usability testing in procurement contracts.", evidenceQuote: "procurement contracts", skillTag: "matching_information"),
            ExamQuestion(id: "\(examID)-R17", number: 17, format: .yesNoNotGiven, prompt: "Twentieth-century prototypes sometimes failed because social and economic factors were overlooked.", options: ["YES", "NO", "NOT GIVEN"], acceptedAnswers: ["YES"], explanation: "Paragraph A states narrow framing produced prototypes that failed in everyday settings.", evidenceQuote: "narrow framing", skillTag: "ynng"),
            ExamQuestion(id: "\(examID)-R18", number: 18, format: .yesNoNotGiven, prompt: "Automated controls completely removed the need for human operators in the \(bp.city) study.", options: ["YES", "NO", "NOT GIVEN"], acceptedAnswers: ["NO"], explanation: "Paragraph B states operators manually overrode automated schedules.", evidenceQuote: "override", skillTag: "ynng"),
            ExamQuestion(id: "\(examID)-R19", number: 19, format: .yesNoNotGiven, prompt: "Participatory usability testing doubles the financial cost of public infrastructure projects.", options: ["YES", "NO", "NOT GIVEN"], acceptedAnswers: ["NOT GIVEN"], explanation: "Paragraph D mentions four weeks of extra time, not doubling financial cost.", evidenceQuote: "four weeks", skillTag: "ynng"),
            ExamQuestion(id: "\(examID)-R20", number: 20, format: .diagramLabeling, prompt: "Stage 1 of the contemporary diagnostic loop (TWO WORDS):", acceptedAnswers: ["baseline mapping"], maxWordCount: 2, explanation: "Paragraph B lists baseline mapping as stage 1.", evidenceQuote: "baseline mapping", skillTag: "diagram_labeling"),
            ExamQuestion(id: "\(examID)-R21", number: 21, format: .diagramLabeling, prompt: "Stage 2 of the contemporary diagnostic loop (THREE WORDS):", acceptedAnswers: ["iterative pilot testing", "pilot testing"], maxWordCount: 3, explanation: "Paragraph B lists iterative pilot testing as stage 2.", evidenceQuote: "iterative pilot testing", skillTag: "diagram_labeling"),
            ExamQuestion(id: "\(examID)-R22", number: 22, format: .diagramLabeling, prompt: "Stage 3 of the contemporary diagnostic loop (TWO WORDS):", acceptedAnswers: ["post-occupancy evaluation"], maxWordCount: 2, explanation: "Paragraph B lists post-occupancy evaluation as stage 3.", evidenceQuote: "post-occupancy evaluation", skillTag: "diagram_labeling"),
            ExamQuestion(id: "\(examID)-R23", number: 23, format: .summaryCompletion, prompt: "Transparent visual ___ helped operators understand real-time trade-offs (ONE WORD):", acceptedAnswers: ["dashboards"], maxWordCount: 1, explanation: "Paragraph C states designers introduced transparent visual dashboards.", evidenceQuote: "dashboards", skillTag: "summary_completion"),
            ExamQuestion(id: "\(examID)-R24", number: 24, format: .tableCompletion, prompt: "Time required for manual overrides to decline sharply (TWO WORDS):", acceptedAnswers: ["six months"], maxWordCount: 2, explanation: "Paragraph C reports results within six months.", evidenceQuote: "six months", skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R25", number: 25, format: .tableCompletion, prompt: "Additional project duration added by participatory testing (TWO WORDS):", acceptedAnswers: ["four weeks"], maxWordCount: 2, explanation: "Paragraph D states roughly four weeks.", evidenceQuote: "four weeks", skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R26", number: 26, format: .matchingSentenceEndings, prompt: "Complete the sentence: Embedding usability testing early prevents ___", options: ["A. costly retrofits later", "B. all software updates", "C. international trade"], acceptedAnswers: ["A", "A. costly retrofits later", "costly retrofits"], explanation: "Paragraph D states it prevents costly retrofits.", evidenceQuote: "costly retrofits", skillTag: "matching_endings")
        ]

        // Passage 3 (14 questions: Q27–40)
        let p3Paragraphs = [
            "Debates within \(bp.discipline3) frequently centre on how rapidly emerging evidence should reshape national regulation. Scholars advocating the precautionary principle argue that waiting for absolute statistical certainty before acting on \(bp.keyTerm3) risks irreversible ecological or economic harm. By contrast, incrementalists contend that premature mandates can lock institutions into immature technologies and alienate practitioners whose cooperation is vital.",
            "Comparative policy reviews across Europe and North America suggest a middle path known as adaptive governance. Under this approach, regulators establish transparent outcome targets while revising technical standards every three years as empirical datasets mature. In \(bp.discipline3), adaptive frameworks have outperformed rigid command-and-control statutes by encouraging local experimentation while preserving strict accountability.",
            "A central obstacle, however, lies in data interoperability. Municipal agencies, universities, and private laboratories often archive measurements in incompatible formats, delaying meta-analyses that could clarify regional trends. Open metadata standards and shared repositories have begun closing this gap, allowing independent auditors to replicate findings without proprietary barriers.",
            "Looking ahead, policy scholars emphasize that technical excellence alone cannot sustain public legitimacy. Citizens are far more likely to support ambitious \(bp.theme) reforms when transition costs are distributed equitably and when independent review panels publish both successes and setbacks candidly."
        ]

        let p3Questions: [ExamQuestion] = [
            ExamQuestion(id: "\(examID)-R27", number: 27, format: .matchingFeatures, prompt: "Which group warns that waiting for total certainty risks irreversible harm?", options: ["A. Precautionary principle advocates", "B. Incrementalists", "C. Proprietary software vendors"], acceptedAnswers: ["A", "A. Precautionary principle advocates"], explanation: "Paragraph A attributes this argument to precautionary principle advocates.", evidenceQuote: "precautionary principle", skillTag: "matching_features"),
            ExamQuestion(id: "\(examID)-R28", number: 28, format: .matchingFeatures, prompt: "Which group warns that premature mandates may lock in immature technologies?", options: ["A. Precautionary principle advocates", "B. Incrementalists", "C. Municipal auditors"], acceptedAnswers: ["B", "B. Incrementalists"], explanation: "Paragraph A states incrementalists raise this concern.", evidenceQuote: "incrementalists", skillTag: "matching_features"),
            ExamQuestion(id: "\(examID)-R29", number: 29, format: .sentenceCompletion, prompt: "The middle-path regulatory model described in Paragraph B is called ___ (TWO WORDS):", acceptedAnswers: ["adaptive governance"], maxWordCount: 2, explanation: "Paragraph B introduces adaptive governance.", evidenceQuote: "adaptive governance", skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R30", number: 30, format: .shortAnswer, prompt: "How frequently are technical standards revised under adaptive governance? (TWO WORDS):", acceptedAnswers: ["three years", "every three years"], maxWordCount: 3, explanation: "Paragraph B states every three years.", evidenceQuote: "three years", skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R31", number: 31, format: .yesNoNotGiven, prompt: "Adaptive frameworks have generally performed better than rigid command-and-control statutes.", options: ["YES", "NO", "NOT GIVEN"], acceptedAnswers: ["YES"], explanation: "Paragraph B explicitly states adaptive frameworks have outperformed rigid command-and-control statutes.", evidenceQuote: "outperformed", skillTag: "ynng"),
            ExamQuestion(id: "\(examID)-R32", number: 32, format: .yesNoNotGiven, prompt: "Incompatible data formats have accelerated regional meta-analyses.", options: ["YES", "NO", "NOT GIVEN"], acceptedAnswers: ["NO"], explanation: "Paragraph C states incompatible formats delay meta-analyses.", evidenceQuote: "delaying meta-analyses", skillTag: "ynng"),
            ExamQuestion(id: "\(examID)-R33", number: 33, format: .yesNoNotGiven, prompt: "All European universities already share a single mandatory database.", options: ["YES", "NO", "NOT GIVEN"], acceptedAnswers: ["NOT GIVEN"], explanation: "The passage notes open standards have begun closing the gap, not that all universities share one mandatory database.", evidenceQuote: "closing this gap", skillTag: "ynng"),
            ExamQuestion(id: "\(examID)-R34", number: 34, format: .summaryCompletion, prompt: "A major technical barrier to cross-agency synthesis is data ___ (ONE WORD):", acceptedAnswers: ["interoperability"], maxWordCount: 1, explanation: "Paragraph C identifies data interoperability as a central obstacle.", evidenceQuote: "interoperability", skillTag: "summary_completion"),
            ExamQuestion(id: "\(examID)-R35", number: 35, format: .summaryCompletion, prompt: "Shared repositories help independent auditors ___ findings without proprietary barriers (ONE WORD):", acceptedAnswers: ["replicate"], maxWordCount: 1, explanation: "Paragraph C states independent auditors can replicate findings.", evidenceQuote: "replicate", skillTag: "summary_completion"),
            ExamQuestion(id: "\(examID)-R36", number: 36, format: .multipleChoice, prompt: "According to Paragraph D, what strengthens public support for major reforms?", options: ["A. Hiding project setbacks", "B. Equitable cost distribution and candid reporting", "C. Eliminating independent review panels"], acceptedAnswers: ["B", "B. Equitable cost distribution and candid reporting"], explanation: "Paragraph D cites equitable distribution of transition costs and candid publication of successes and setbacks.", evidenceQuote: "equitably", skillTag: "multiple_choice"),
            ExamQuestion(id: "\(examID)-R37", number: 37, format: .matchingSentenceEndings, prompt: "Adaptive governance encourages local experimentation while preserving ___", options: ["A. strict accountability", "B. permanent subsidies", "C. closed datasets"], acceptedAnswers: ["A", "A. strict accountability", "strict accountability"], explanation: "Paragraph B states it preserves strict accountability.", evidenceQuote: "strict accountability", skillTag: "matching_endings"),
            ExamQuestion(id: "\(examID)-R38", number: 38, format: .matchingSentenceEndings, prompt: "Open metadata standards help overcome ___", options: ["A. incompatible measurement formats", "B. extreme weather events", "C. staff shortages"], acceptedAnswers: ["A", "A. incompatible measurement formats"], explanation: "Paragraph C connects open metadata standards to resolving incompatible formats.", evidenceQuote: "metadata standards", skillTag: "matching_endings"),
            ExamQuestion(id: "\(examID)-R39", number: 39, format: .shortAnswer, prompt: "What key concept in Paragraph A triggers debate over regulatory timing? (ONE OR TWO WORDS):", acceptedAnswers: [bp.keyTerm3], maxWordCount: 2, explanation: "Paragraph A centres on acting on \(bp.keyTerm3).", evidenceQuote: bp.keyTerm3, skillTag: "scanning"),
            ExamQuestion(id: "\(examID)-R40", number: 40, format: .multipleChoice, prompt: "Which title best summarizes Passage 3?", options: ["A. Balancing Evidence, Governance, and Public Trust", "B. Why All Regulations Should Be Abolished", "C. A Biography of Early Statisticians"], acceptedAnswers: ["A", "A. Balancing Evidence, Governance, and Public Trust"], explanation: "Passage 3 synthesizes precautionary vs incremental regulation, adaptive governance, open data, and public legitimacy.", evidenceQuote: "public legitimacy", skillTag: "main_idea")
        ]

        return [
            ReadingPassage(id: "\(examID)-RP1", passageNumber: 1, title: "Field Evidence in \(bp.discipline1)", discipline: bp.discipline1, paragraphs: p1Paragraphs, questions: p1Questions),
            ReadingPassage(id: "\(examID)-RP2", passageNumber: 2, title: "Human-Centred Design in \(bp.discipline2)", discipline: bp.discipline2, paragraphs: p2Paragraphs, questions: p2Questions),
            ReadingPassage(id: "\(examID)-RP3", passageNumber: 3, title: "Adaptive Governance in \(bp.discipline3)", discipline: bp.discipline3, paragraphs: p3Paragraphs, questions: p3Questions)
        ]
    }

    // MARK: - Writing Task 1 Builder

    private static func buildWritingTask1(examID: String, bp: ExamBlueprint) -> WritingTask1Prompt {
        let y1 = "\(bp.yearStart)"
        let y2 = "\(bp.yearStart + 4)"
        let y3 = "\(bp.yearStart + 8)"
        let base = Double(bp.metricValue)

        let dataPoints: [VisualDataPoint] = [
            VisualDataPoint(series: "Region A (\(bp.city))", category: y1, value: base, unit: bp.unit),
            VisualDataPoint(series: "Region A (\(bp.city))", category: y2, value: base + 11, unit: bp.unit),
            VisualDataPoint(series: "Region A (\(bp.city))", category: y3, value: base + 23, unit: bp.unit),
            VisualDataPoint(series: "National Average", category: y1, value: max(8, base - 6), unit: bp.unit),
            VisualDataPoint(series: "National Average", category: y2, value: max(12, base + 2), unit: bp.unit),
            VisualDataPoint(series: "National Average", category: y3, value: base + 9, unit: bp.unit)
        ]

        let processSteps: [String] = bp.visualType == .processDiagram ? [
            "1. Raw Input Collection & Quality Screening (\(bp.keyTerm1))",
            "2. Controlled Processing & Conditioning (\(bp.keyTerm2))",
            "3. Automated Sensor Verification & Stabilization",
            "4. Distribution, Field Application & Monitoring (\(bp.keyTerm3))",
            "5. Feedback Audit & Circular Recovery"
        ] : []

        return WritingTask1Prompt(
            id: "\(examID)-wt1",
            title: "Mock \(bp.number) Task 1: \(bp.visualType.rawValue) — \(bp.discipline1)",
            visualType: bp.visualType,
            instructions: "The \(bp.visualType.rawValue.lowercased()) below illustrates changes in \(bp.discipline1) performance (\(bp.unit)) between \(y1) and \(y3) in \(bp.city) compared with the national average. Summarize the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.",
            minimumWords: 150,
            dataPoints: dataPoints,
            processSteps: processSteps,
            keyOverviewPoints: [
                "Both Region A (\(bp.city)) and the National Average experienced consistent upward growth from \(y1) to \(y3).",
                "Region A outperformed the National Average throughout the entire timeframe, widening its lead by \(y3)."
            ]
        )
    }

    // MARK: - Speaking Builder (Parts 1, 2, 3)

    private static func buildSpeakingSet(examID: String, bp: ExamBlueprint) -> SpeakingPromptSet {
        SpeakingPromptSet(
            id: "\(examID)-spk",
            theme: bp.theme,
            part1Questions: [
                "Do you currently work or study, and what do you find most interesting about your field?",
                "How much do people in your hometown pay attention to \(bp.theme.lowercased())?",
                "Have your daily habits related to \(bp.discipline1.lowercased()) or technology changed over the past five years?",
                "Do you prefer reading printed articles or listening to talks when learning about new topics?"
            ],
            part2CueCard: SpeakingCueCard(
                topic: "Describe \(bp.speakingTopic).",
                bulletPoints: [
                    "What it is and when you first encountered it",
                    "Why it caught your attention",
                    "How it relates to modern society or your personal goals",
                    "And explain why you think it is significant"
                ],
                prepSeconds: 60,
                speakSeconds: 120
            ),
            part3Questions: [
                "How can governments encourage wider public adoption of evidence-based practices in \(bp.theme.lowercased())?",
                "Do you think universities focus enough on practical real-world challenges alongside theory?",
                "What economic or social barriers make long-term reforms difficult to implement?",
                "How might international collaboration in \(bp.discipline1.lowercased()) evolve over the next two decades?"
            ]
        )
    }
}


/// Namespace for hand-authored exams. Each exam lives in its own `AuthoredExamNN.swift` file.
public enum AuthoredExams {
    public static var all: [MockExam] { [exam01, exam02] }
}

extension MockExam {
    /// Returns a copy whose provenance records the bank-level validation result.
    func withValidation(_ report: ContentValidationReport, generatorModel: String?) -> MockExam {
        let notes = report.passed
            ? ["Passed bank validation: 4 Listening parts / 40 questions, 3 Reading passages / 40 questions, evidence found in source text, no within-exam or cross-exam duplicates."] + provenance.validationNotes
            : report.issues
        return MockExam(
            id: id, examNumber: examNumber, title: title, difficulty: difficulty, theme: theme,
            listeningParts: listeningParts, readingPassages: readingPassages,
            writingTask1: writingTask1, writingTask2: writingTask2, speakingSet: speakingSet,
            provenance: ContentProvenance(
                origin: provenance.origin,
                isOfficialIELTSMaterial: false,
                generatorModel: generatorModel,
                validatedAt: report.validatedAt,
                validationPassed: report.passed,
                validationNotes: notes,
                sourceReferenceIDs: provenance.sourceReferenceIDs.isEmpty ? ["src-ielts-org", "src-british-council", "src-idp-ielts"] : provenance.sourceReferenceIDs
            )
        )
    }
}
